  "noticeReopen": "Salvestusteade",
  "noticeLabel": "Brauseri salvestuse teade",
  "noticeText": "Cook kasutab brauseri salvestust sinu kasutatavate toiduvalmistamis- ja sisselogimisfunktsioonide jaoks. Reklaami- ega analüütikasalvestust ei lisata.",
  "noticeClose": "Sulge salvestusteade",
  "privDraftLabel": "Mustand – uuendatud 28. oktoobril 2026.",
  "privDraft": "Kontofunktsioone testitakse praegu. Allpool olevad haldaja ja teenuste andmed tuleb enne avalikku käivitamist täiendada.",
  "privWho1": "Cooki haldab [haldaja ametlik nimi ja postiaadress]. Privaatsusküsimuste ja -taotlustega pöördu aadressil [privaatsuse e-posti aadress]. Need andmed tuleb täiendada enne registreerimise avamist.",
  "privWhat1": "Konto loomisel kasutame sinu e-posti aadressi, konto identifikaatorit, parooliga autentimise andmeid ja kinnitamise olekut, et pakkuda ja kaitsta sinu kontot. Autentimisteenuse pakkuja töötleb paroole turvaliste räsidena; Cook ei salvesta loetavaid paroole. Salvestame köögi paigutuse, valitud keele, teema ja mõõtühikud, et taastada sinu seaded kõigis seadmetes. Konto jaoks on vaja e-posti aadressi ja parooli; retsepte saad sirvida ka ilma kontota.",
  "privWhat2": "Konto ja seadete töötlemine on vajalik sinu soovitud kontoteenuse osutamiseks (isikuandmete kaitse üldmääruse artikli 6 lõike 1 punkt b). Piiratud turva- ja kuritarvituste ennetamise andmeid võidakse töödelda õigustatud huvi alusel (artikli 6 lõike 1 punkt f), kui see on vajalik ja huvide kaalumine seda lubab. Kinnitus- ja parooli lähtestamise kirjad on teenusesõnumid, mitte turundus. Kontofunktsioon ei lisa reklaami ega analüütikat.",
  "privStorage1": "Cook kasutab sessionStorage’it, et kanda sinu köök, toiduvalmistamise edenemine ja valikud sama vahekaardi lehtede vahel üle. Sisselogituna hoiab see ka sinu sisselogimisseanssi. Brauser kustutab selle tavaliselt vahekaardi seansi lõppedes, kuid brauseri seansi taastamine võib selle säilitada. Väljalogimine kustutab Cooki vahekaardi andmed. Salvestusteate sulgemine jäetakse meelde ainult selles vahekaardis. Cooki enda skriptid ei sea küpsiseid. Sinu majutus- või teenusepakkujatel võib olla oma turvatöötlus, mis tuleb enne käivitamist dokumenteerida.",
  "privStorage2": "OK ja salvestusteate sulgemisnupp ainult sulgevad teate. Need ei luba analüütikat, reklaami ega muud valikulist jälgimist. Iga tulevane mittevajalik salvestus nõuab enne algust eraldi valikut, kus keeldumine ja tagasivõtmine on sama lihtsad.",
  "privOther1": "Retseptiloendi praegune kõnefunktsioon küsib country.is-ilt sinu IP-aadressi põhjal ligikaudse riigi, et valida kõnekeel. Kui kasutad mikrofoniga tuvastust, võib brauser saata heli oma kõnetuvastusteenuse pakkujale. Koostisosi saad ka sisse trükkida. Need pakkujad, nende põhimõtted ja nende funktsioonide õiguslik alus tuleb enne avalikku käivitamist üle vaadata.",
  "privProviders1": "Kavandatud kontoteenuse pakkuja: Supabase (hallatud PostgreSQL ja autentimine) valitud ELi andmebaasipiirkonnaga. E-posti teenuse pakkuja: [pakkuja]. Veebimajutus: [pakkuja]. Haldaja peab kinnitama tegelikud pakkujad, töötluslepingud, alamtöötlejad, logide asukohad ja võimalikud edastused väljapoole EMPd. ELi andmebaasipiirkond ei välista iseenesest rahvusvahelisi edastusi. Vajaduse korral tuleb märkida kohaldatav kaitse piisavuse otsus või lepingulised kaitsemeetmed ja kuidas saada nende koopia.",
  "privRetention1": "Konto seadeid hoitakse seni, kuni sinu konto on aktiivne. Kustutamist saad taotleda ülal toodud privaatsuskontakti kaudu. Enne käivitamist peab haldaja määrama kustutustaotlustele vastamise korra, kinnitamata kontode aegumise ning turvalogide ja varukoopiate säilitusajad. Kustutatud andmed võivad jääda piiratud juurdepääsuga varukoopiatesse kuni dokumenteeritud säilitusaja lõpuni.",
  "privRights1": "Olenevalt kohaldatavatest tingimustest võid taotleda juurdepääsu, parandamist, kustutamist, piiramist või ülekandmist või esitada vastuväite õigustatud huvil põhinevale töötlemisele. Võta ühendust ülal nimetatud haldajaga; taotlustele vastatakse tavaliselt ühe kuu jooksul ja võimalikku seaduslikku pikendamist selgitatakse. Võid esitada kaebuse järelevalveasutusele, sealhulgas Ungari NAIH-le aadressil naih.hu. Cook ei kasuta konto seadeid automatiseeritud otsusteks, millel on õiguslik või samaväärselt oluline mõju.",
